// Both spellings are generated by Racket when the manual is built.
// Without JavaScript, their labelled panels remain visible.
document.addEventListener("DOMContentLoaded", () => {
  const examples = [...document.querySelectorAll(".code-example")];
  const storageKey = "sciencelogo.example-syntax";
  const syntaxes = ["compact", "verbose"];
  let selected = "compact";
  try {
    const saved = localStorage.getItem(storageKey);
    if (syntaxes.includes(saved)) selected = saved;
  } catch (_) {
    // Switching still works when the browser does not allow local storage.
  }

  const groups = [];
  function choose(syntax, remember = true) {
    selected = syntax;
    for (const { buttons, panels } of groups) {
      for (const name of syntaxes) {
        const active = name === syntax;
        buttons[name].setAttribute("aria-selected", String(active));
        buttons[name].tabIndex = active ? 0 : -1;
        panels[name].hidden = !active;
      }
    }
    if (remember) {
      try {
        localStorage.setItem(storageKey, syntax);
      } catch (_) {
        // Keep the selection for this page even if it cannot be saved.
      }
    }
  }

  examples.forEach((example, index) => {
    const compact = example.querySelector('[data-syntax="compact"]');
    const verbose = example.querySelector('[data-syntax="verbose"]');
    if (!compact || !verbose) return;

    const panels = { compact, verbose };
    const buttons = {};
    const tabs = document.createElement("div");
    tabs.className = "code-example-tabs";
    tabs.setAttribute("role", "tablist");
    tabs.setAttribute("aria-label", "Example syntax");

    for (const name of syntaxes) {
      const button = document.createElement("button");
      button.type = "button";
      button.id = `code-example-${index}-${name}-tab`;
      button.textContent = name === "compact" ? "Compact" : "Verbose";
      button.setAttribute("role", "tab");
      button.setAttribute("aria-controls", `code-example-${index}-${name}`);
      panels[name].id = `code-example-${index}-${name}`;
      panels[name].setAttribute("role", "tabpanel");
      panels[name].setAttribute("aria-labelledby", button.id);
      panels[name].tabIndex = 0;
      buttons[name] = button;
      tabs.append(button);
      button.addEventListener("click", () => choose(name));
      button.addEventListener("keydown", (event) => {
        if (event.altKey || event.ctrlKey || event.metaKey) return;
        let next;
        if (event.key === "ArrowLeft" || event.key === "ArrowRight") {
          next = name === "compact" ? "verbose" : "compact";
        } else if (event.key === "Home") next = "compact";
        else if (event.key === "End") next = "verbose";
        else return;
        event.preventDefault();
        choose(next);
        buttons[next].focus();
      });
    }
    groups.push({ buttons, panels });
    example.prepend(tabs);
    example.dataset.enhanced = "true";
  });
  choose(selected, false);

  window.addEventListener("storage", (event) => {
    if (event.key === storageKey && syntaxes.includes(event.newValue)) {
      choose(event.newValue, false);
    }
  });
});
